74	namespace {
75	void overrideWithEnv(Option& op,
76	                     const std::shared_ptr<OptionParser>& optionParser,
77	                     PrefPtr pref, const std::string& envName)
78	{
79	  char* value = getenv(envName.c_str());
80	  if (value) {
81	    try {
82	      optionParser->find(pref)->parse(op, value);
83	    }
84	    catch (Exception& e) {
85	      global::cerr()->printf(
86	          _("Caught Error while parsing environment variable '%s'"),
87	          envName.c_str());
88	      global::cerr()->printf("\n%s\n", e.stackTrace().c_str());
89	    }
90	  }
91	}
92	} // namespace
