94	namespace {
95	// Calculates Damerau–Levenshtein distance between c-string a and b
96	// with given costs.  swapcost, subcost, addcost and delcost are cost
97	// to swap 2 adjacent characters, substitute characters, add character
98	// and delete character respectively.
99	int levenshtein(const char* a, const char* b, int swapcost, int subcost,
100	                int addcost, int delcost)
101	{
102	  int alen = strlen(a);
103	  int blen = strlen(b);
104	  std::vector<std::vector<int>> dp(3, std::vector<int>(blen + 1));
105	  for (int i = 0; i <= blen; ++i) {
106	    dp[1][i] = i * addcost;
107	  }
108	  for (int i = 1; i <= alen; ++i) {
109	    dp[0][0] = i * delcost;
110	    for (int j = 1; j <= blen; ++j) {
111	      dp[0][j] = dp[1][j - 1] + (a[i - 1] == b[j - 1] ? 0 : subcost);
112	      if (i >= 2 && j >= 2 && a[i - 1] != b[j - 1] && a[i - 2] == b[j - 1] &&
113	          a[i - 1] == b[j - 2]) {
114	        dp[0][j] = std::min(dp[0][j], dp[2][j - 2] + swapcost);
115	      }
116	      dp[0][j] = std::min(dp[0][j],
117	                          std::min(dp[1][j] + delcost, dp[0][j - 1] + addcost));
118	    }
119	    std::rotate(dp.begin(), dp.begin() + 2, dp.end());
120	  }
121	  return dp[1][blen];
122	}
