174	error_code::Value option_processing(Option& op, bool standalone,
175	                                    std::vector<std::string>& uris, int argc,
176	                                    char** argv, const KeyVals& options)
177	{
178	  const std::shared_ptr<OptionParser>& oparser = OptionParser::getInstance();
179	  try {
180	    bool noConf = false;
181	    std::string ucfname;
182	    std::stringstream cmdstream;
183	    {
184	      // first evaluate --no-conf and --conf-path options.
185	      Option op;
186	      if (argc == 0) {
187	        oparser->parse(op, options);
188	      }
189	      else {
190	        oparser->parseArg(cmdstream, uris, argc, argv);
191	        oparser->parse(op, cmdstream);
192	      }
193	      noConf = op.getAsBool(PREF_NO_CONF);
194	      ucfname = op.get(PREF_CONF_PATH);
195	      if (standalone) {
196	        if (op.defined(PREF_VERSION)) {
197	          showVersion();
198	          exit(error_code::FINISHED);
199	        }
200	        if (op.defined(PREF_HELP)) {
201	          std::string keyword;
202	          if (op.get(PREF_HELP).empty()) {
203	            keyword = strHelpTag(TAG_BASIC);
204	          }
205	          else {
206	            keyword = op.get(PREF_HELP);
207	            if (util::startsWith(keyword, "--")) {
208	              keyword.erase(keyword.begin(), keyword.begin() + 2);
209	            }
210	            std::string::size_type eqpos = keyword.find("=");
211	            if (eqpos != std::string::npos) {
212	              keyword.erase(keyword.begin() + eqpos, keyword.end());
213	            }
214	          }
215	          showUsage(keyword, oparser, global::cout());
216	          exit(error_code::FINISHED);
217	        }
218	      }
219	    }
220	    auto confOption = std::make_shared<Option>();
221	    oparser->parseDefaultValues(*confOption);
222	    if (!noConf) {
223	      std::string cfname =
224	          ucfname.empty() ? oparser->find(PREF_CONF_PATH)->getDefaultValue()
225	                          : ucfname;
226	
227	      if (File(cfname).isFile()) {
228	        std::stringstream ss;
229	        {
230	          BufferedFile fp(cfname.c_str(), BufferedFile::READ);
231	          if (fp) {
232	            fp.transfer(ss);
233	          }
234	        }
235	        try {
236	          oparser->parse(*confOption, ss);
237	        }
238	        catch (OptionHandlerException& e) {
239	          global::cerr()->printf(_("Parse error in %s"), cfname.c_str());
240	          global::cerr()->printf("\n%s", e.stackTrace().c_str());
241	          const OptionHandler* h = oparser->find(e.getPref());
242	          if (h) {
243	            global::cerr()->printf(_("Usage:"));
244	            global::cerr()->printf("\n%s\n", h->getDescription());
245	          }
246	          return e.getErrorCode();
247	        }
248	        catch (Exception& e) {
249	          global::cerr()->printf(_("Parse error in %s"), cfname.c_str());
250	          global::cerr()->printf("\n%s", e.stackTrace().c_str());
251	          return e.getErrorCode();
252	        }
253	      }
254	      else if (!ucfname.empty()) {
255	        global::cerr()->printf(_("Configuration file %s is not found."),
256	                               cfname.c_str());
257	        global::cerr()->printf("\n");
258	        showUsage(strHelpTag(TAG_HELP), oparser, global::cerr());
259	        return error_code::UNKNOWN_ERROR;
260	      }
261	    }
262	    // Override configuration with environment variables.
263	    overrideWithEnv(*confOption, oparser, PREF_HTTP_PROXY, "http_proxy");
264	    overrideWithEnv(*confOption, oparser, PREF_HTTPS_PROXY, "https_proxy");
265	    overrideWithEnv(*confOption, oparser, PREF_FTP_PROXY, "ftp_proxy");
266	    overrideWithEnv(*confOption, oparser, PREF_ALL_PROXY, "all_proxy");
267	    overrideWithEnv(*confOption, oparser, PREF_NO_PROXY, "no_proxy");
268	    if (!standalone) {
269	      // For non-standalone mode, set PREF_QUIET to true to suppress
270	      // output. The caller can override this by including PREF_QUIET
271	      // in options argument.
272	      confOption->put(PREF_QUIET, A2_V_TRUE);
273	    }
274	
275	    // we must clear eof bit and seek to the beginning of the buffer.
276	    cmdstream.clear();
277	    cmdstream.seekg(0, std::ios::beg);
278	    // finally let's parse and store command-line options.
279	    op.setParent(confOption);
280	    oparser->parse(op, cmdstream);
281	    oparser->parse(op, options);
282	  }
283	  catch (OptionHandlerException& e) {
284	    global::cerr()->printf("%s", e.stackTrace().c_str());
285	    const OptionHandler* h = oparser->find(e.getPref());
286	    if (h) {
287	      global::cerr()->printf(_("Usage:"));
288	      global::cerr()->printf("\n");
289	      write(global::cerr(), *h);
290	    }
291	    return e.getErrorCode();
292	  }
293	  catch (UnknownOptionException& e) {
294	    showUsage("", oparser, global::cerr());
295	    showCandidates(e.getUnknownOption(), oparser);
296	    return e.getErrorCode();
297	  }
298	  catch (Exception& e) {
299	    global::cerr()->printf("%s", e.stackTrace().c_str());
300	    showUsage("", oparser, global::cerr());
301	    return e.getErrorCode();
302	  }
303	  if (standalone && op.getAsBool(PREF_STDERR)) {
304	    global::redirectStdoutToStderr();
305	  }
306	  if (standalone && !op.getAsBool(PREF_ENABLE_RPC) &&
307	#ifdef ENABLE_BITTORRENT
308	      op.blank(PREF_TORRENT_FILE) &&
309	#endif // ENABLE_BITTORRENT
310	#ifdef ENABLE_METALINK
311	      op.blank(PREF_METALINK_FILE) &&
312	#endif // ENABLE_METALINK
313	      op.blank(PREF_INPUT_FILE)) {
314	    if (uris.empty()) {
315	      global::cerr()->printf(MSG_URI_REQUIRED);
316	      global::cerr()->printf("\n");
317	      showUsage("", oparser, global::cerr());
318	      return error_code::UNKNOWN_ERROR;
319	    }
320	  }
321	  if (standalone && op.getAsBool(PREF_DAEMON)) {
322	#if defined(__GNUC__) && defined(__APPLE__)
323	// daemon() is deprecated on OSX since... forever.
324	// Silence the warning for good, so that -Werror becomes feasible.
325	#  pragma GCC diagnostic push
326	#  pragma GCC diagnostic ignored "-Wdeprecated-declarations"
327	#endif // defined(__GNUC__) && defined(__APPLE__)
328	    const auto daemonized = daemon(0, 0);
329	#if defined(__GNUC__) && defined(__APPLE__)
330	#  pragma GCC diagnostic pop
331	#endif // defined(__GNUC__) && defined(__APPLE__)
332	
333	    if (daemonized < 0) {
334	      perror(MSG_DAEMON_FAILED);
335	      return error_code::UNKNOWN_ERROR;
336	    }
337	  }
338	  if (op.getAsBool(PREF_DEFERRED_INPUT) && op.defined(PREF_SAVE_SESSION)) {
339	    A2_LOG_WARN("--deferred-input is disabled because of the presence of "
340	                "--save-session");
341	    op.remove(PREF_DEFERRED_INPUT);
342	  }
343	
344	  return error_code::FINISHED;
345	}
346	
347	} // namespace aria2
