127	void showCandidates(const std::string& unknownOption,
128	                    const std::shared_ptr<OptionParser>& parser)
129	{
130	  const char* optstr = unknownOption.c_str();
131	  for (; *optstr == '-'; ++optstr)
132	    ;
133	  if (*optstr == '\0') {
134	    return;
135	  }
136	  int optstrlen = strlen(optstr);
137	  std::vector<std::pair<int, PrefPtr>> cands;
138	  for (int i = 1, len = option::countOption(); i < len; ++i) {
139	    PrefPtr pref = option::i2p(i);
140	    const OptionHandler* h = parser->find(pref);
141	    if (!h || h->isHidden()) {
142	      continue;
143	    }
144	    // Use cost 0 for prefix match
145	    if (util::startsWith(pref->k, pref->k + strlen(pref->k), optstr,
146	                         optstr + optstrlen)) {
147	      cands.push_back(std::make_pair(0, pref));
148	      continue;
149	    }
150	    // cost values are borrowed from git, help.c.
151	    int sim = levenshtein(optstr, pref->k, 0, 2, 1, 3);
152	    cands.push_back(std::make_pair(sim, pref));
153	  }
154	  if (cands.empty()) {
155	    return;
156	  }
157	  std::sort(cands.begin(), cands.end());
158	  int threshold = cands[0].first;
159	  // threshold value 12 is a magic value.
160	  if (threshold > 12) {
161	    return;
162	  }
163	  global::cerr()->printf("\n");
164	  global::cerr()->printf(_("Did you mean:"));
165	  global::cerr()->printf("\n");
166	  for (auto i = cands.begin(), eoi = cands.end();
167	       i != eoi && (*i).first <= threshold; ++i) {
168	    global::cerr()->printf("\t--%s\n", (*i).second->k);
169	  }
170	}
