291	void OptionParser::parseDefaultValues(Option& option) const
292	{
293	  for (const auto& h : handlers_) {
294	    if (h && !h->getDefaultValue().empty()) {
295	      h->parse(option, h->getDefaultValue());
296	    }
297	  }
298	}
