117	int32_t Option::getAsInt(PrefPtr pref) const
118	{
119	  const std::string& value = get(pref);
120	  if (value.empty()) {
121	    return 0;
122	  }
123	  else {
124	    return strtol(value.c_str(), nullptr, 10);
125	  }
126	}
127	
128	int64_t Option::getAsLLInt(PrefPtr pref) const
129	{
130	  const std::string& value = get(pref);
131	  if (value.empty()) {
132	    return 0;
133	  }
134	  else {
135	    return strtoll(value.c_str(), nullptr, 10);
136	  }
137	}
