152	void Option::removeLocal(PrefPtr pref)
153	{
154	  unsetBit(use_, pref);
155	  table_[pref->i].clear();
156	}
157	
158	void Option::remove(PrefPtr pref)
159	{
160	  removeLocal(pref);
161	  if (parent_) {
162	    parent_->remove(pref);
163	  }
164	}
165	
166	void Option::clear()
167	{
168	  std::fill(use_.begin(), use_.end(), 0);
169	  std::fill(table_.begin(), table_.end(), "");
170	}
171	
172	void Option::merge(const Option& option)
173	{
174	  size_t bits = option.use_.size() * 8;
175	  for (size_t i = 1, len = table_.size(); i < len; ++i) {
176	    if (bitfield::test(option.use_, bits, i)) {
177	      use_[i / 8] |= 128 >> (i % 8);
178	      table_[i] = option.table_[i];
179	    }
180	  }
181	}
