56	  std::string possibleValues = optionHandler.createPossibleValuesString();
57	  if (!possibleValues.empty()) {
58	    o << POSSIBLE_MSG << possibleValues << "\n";
59	  }
60	  if (!optionHandler.getDefaultValue().empty()) {
61	    o << DEFAULT_MSG << optionHandler.getDefaultValue() << "\n";
62	  }
